import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import SearchForm from '../components/SearchForm';
import RouteList from '../components/RouteList';
import { useNavigate } from 'react-router-dom';
import '../styles/home.css';

const Home = () => {
  const [routes, setRoutes] = useState([]);
  const [filteredRoutes, setFilteredRoutes] = useState([]);
  const [searchPerformed, setSearchPerformed] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [hasFormFocus, setHasFormFocus] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const checkEmailConfirmation = () => {
      const urlParams = new URLSearchParams(window.location.search);
      if (urlParams.get('emailConfirmed')) {
        navigate('/', { replace: true });
        setTimeout(() => alert('✅ Ваш email успешно подтвержден!'), 300);
      }
    };

    const fetchRoutes = async () => {
      try {
        const { data } = await axios.get('/api/routes');
        setRoutes(data);
        setFilteredRoutes(data);
        setIsLoading(false);
      } catch (err) {
        console.error('Ошибка загрузки маршрутов:', err);
        setIsLoading(false);
      }
    };

    checkEmailConfirmation();
    fetchRoutes();
  }, [navigate]);

  const handleSearch = useCallback(({ from, to, date }) => {
    const filtered = routes.filter(route => {
      const matchFrom = from ? route.from?.toLowerCase().includes(from.toLowerCase()) : true;
      const matchTo = to ? route.to?.toLowerCase().includes(to.toLowerCase()) : true;
      const routeDate = new Date(route.date);
      const searchDate = new Date(date);
      return matchFrom && matchTo && (!date || 
        routeDate.getFullYear() === searchDate.getFullYear() &&
        routeDate.getMonth() === searchDate.getMonth() &&
        routeDate.getDate() === searchDate.getDate());
    });
    
    setFilteredRoutes(filtered);
    setSearchPerformed(true);
    window.scrollTo({ top: 500, behavior: 'smooth' });
  }, [routes]);

  const handleFormFocus = useCallback(() => {
    setHasFormFocus(true);
    if (searchPerformed) {
      setSearchPerformed(false);
    }
  }, [searchPerformed]);

  return (
    <div className="home-page">
      <section className="hero-section">
        <div className="hero-content">
          <h1 className="hero-title">Найдите идеальное путешествие</h1>
          <p className="hero-subtitle">Откройте для себя лучшие направления по выгодным ценам</p>
        </div>
      </section>

      <section className="main-layout">
        <div className={`content-wrapper ${searchPerformed ? 'search-done' : 'search-pending'}`}>
          <main className="main-content">
            <SearchForm 
              onSearch={handleSearch}
              onFocus={handleFormFocus}
              wide={!searchPerformed || hasFormFocus}
              isLoading={isLoading}
            />
          </main>

          <aside className={`sidebar ${searchPerformed ? 'visible' : ''}`}>
            {/* ...остальное содержимое сайдбара без изменений */}
          </aside>
        </div>

        {/* ...остальная часть компонента без изменений */}
      </section>

      <section className="features-wrapper">
        {/* ...блок features без изменений */}
      </section>
    </div>
  );
};

export default Home;
